using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.TKT.PrioridadEstickets;namespace GraphApi.Services.TKT.PrioridadEstickets{    public class PrioridadEsticketsService : IPrioridadEsticketsService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public PrioridadEsticketsService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadPrioridadEstickets>> GetPrioridadEstickets(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM tkt.PrioridadEstickets (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadPrioridadEstickets>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetPrioridadEsticketsDynamic(            int? prioridadTicketID,            string? prioridadTicket,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "PrioridadTicketID, PrioridadTicket, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM tkt.PrioridadEstickets (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (prioridadTicketID.HasValue)            {                vSql.Append(" AND PrioridadTicketID = @PrioridadTicketID");                vParameters.Add("PrioridadTicketID",prioridadTicketID);            }            if (!string.IsNullOrWhiteSpace(prioridadTicket))            {                vSql.Append(" AND PrioridadTicket LIKE @PrioridadTicket");                vParameters.Add("PrioridadTicket",$"%{prioridadTicket}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadPrioridadEstickets> CreatePrioridadEstickets(clCreatePrioridadEstickets objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO tkt.PrioridadEstickets                (PrioridadTicket, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@PrioridadTicket, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.PrioridadTicket,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT PrioridadTicketID, PrioridadTicket, bEliminado                FROM tkt.PrioridadEstickets (NOLOCK)                WHERE PrioridadTicketID = @PrioridadTicketID;";            var vReadParams = new { PrioridadTicketID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadPrioridadEstickets>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el PrioridadEsticket con ID {vNewId}.");            return vCreated;        }        public async Task<clReadPrioridadEstickets?> UpdatePrioridadEstickets(clUpdatePrioridadEstickets objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("PrioridadTicketID", objInput.PrioridadTicketID);            if (objInput.PrioridadTicket is not null)            {                vSets.Add("PrioridadTicket = @PrioridadTicket");                vParameters.Add("PrioridadTicket", objInput.PrioridadTicket);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE tkt.PrioridadEstickets                SET {vSetClause}                WHERE PrioridadTicketID = @PrioridadTicketID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT PrioridadTicketID, PrioridadTicket, bEliminado                FROM tkt.PrioridadEstickets (NOLOCK)                WHERE PrioridadTicketID = @PrioridadTicketID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadPrioridadEstickets>(sSelect, new {  objInput.PrioridadTicketID });        }        public async Task<bool> DeletePrioridadEstickets(int nPrioridadEsticketsID)        {            const string sSql = @"                DELETE FROM tkt.PrioridadEstickets                WHERE PrioridadTicketID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nPrioridadEsticketsID });            return vAffected > 0;        }    }}